        this.show_root_folder_data = true;
      }
      if (item.fileIcon == "mdi-folder") {
        this.tableData = [];
        this.breadcrumbsItems.push({
          title: item.FileName,
          text: item.FileName,
          disabled: false,
          currentPath: item.Key
        });
        this.rowInfo = item;
        this.subFolderCheck = true;
        var data = item.Key.split("/");
        if (data.length == 1) {
          this.tableData = [];
          this.selectedPath = item.Key;
          this.get_sub_folders_data(item.Key);
        } else if (data.length > 1) {
          this.tableData = [];
          var urlParts = data;
          urlParts = urlParts.slice(2);
          urlParts = urlParts.filter(part => part !== "");
          let path = urlParts.join("/");
          this.selectedPath = path;
          this.get_sub_folders_data(path);
        }
      } else {
        if (item.fileIcon == "mdi-file" && this.isImageOrPdf(item)) {
          this.view_file(item);
        } else {
          this.rowInfo = item;
        }
      }
    },
    async get_sub_folders_data(item) {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(get_s3_existing_files, {
          input: {
            folder_name: item,
            organization_id: data.organization.organization_id
          }
        }));
        this.tableData = [];
        this.tableLoading = false;
        var response = JSON.parse(result.data.get_s3_existing_files);
        if (response.Status == "SUCCESS") {
          let filesFolders = response.data;
          if (filesFolders.files.length !== 0 || filesFolders.folders.length !== 0) {
            filesFolders.files.concat(filesFolders.folders).forEach(element => {
              this.tableData.push({
                Key: element.Key,
                fileIcon: element.hasOwnProperty("Size") ? "mdi-file" : "mdi-folder",
