                LastModified: element.hasOwnProperty("LastModified") ? this.formatLastModifiedDate(element.LastModified) : "-",
                currentPath: element.Key,
                FileName: element.hasOwnProperty("Size") ? this.fetch_file_names(element.Key) : this.fetch_folder_name(element),
                folderType: "SubFolders",
                folder_created_by_email: ""
              });
            });
          }
          this.tableLoading = false;
          this.totalCount = this.tableData.length;
          this.pageCount = Math.ceil(this.totalCount / this.itemsPerPage);
          this.currentPage = 1;
          this.updatePageItems();
        }
